      out.write("\r\n");
      out.write("\r\n");
      out.write("<script>\r\n");
      out.write("// Dữ liệu tiêu chí hiện tại trong khung\r\n");
      out.write("var criteriaList = [];\r\n");
      out.write("\r\n");
      out.write("// Nếu là chế độ Edit, nạp danh sách tiêu chí có sẵn của framework\r\n");
      if (_jspx_meth_c_005fif_005f4(_jspx_page_context))
        return;
      out.write("\r\n");
      out.write("\r\n");
      out.write("document.addEventListener(\"DOMContentLoaded\", function() {\r\n");
      out.write("    renderCriteriaTable();\r\n");
      out.write("});\r\n");
      out.write("\r\n");
      out.write("function renderCriteriaTable() {\r\n");
      out.write("    var tbody = document.getElementById(\"criteriaTableBody\");\r\n");
      out.write("    var emptyNotice = document.getElementById(\"emptyCriteriaNotice\");\r\n");
      out.write("    tbody.innerHTML = \"\";\r\n");
      out.write("\r\n");
      out.write("    if (criteriaList.length === 0) {\r\n");
      out.write("        emptyNotice.style.display = \"block\";\r\n");
      out.write("    } else {\r\n");
      out.write("        emptyNotice.style.display = \"none\";\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    criteriaList.forEach(function(item, index) {\r\n");
      out.write("        var tr = document.createElement(\"tr\");\r\n");
      out.write("        tr.className = \"criterion-row\";\r\n");
      out.write("        tr.innerHTML = \r\n");
      out.write("            '<td class=\"text-center text-muted small fw-bold\">' + (index + 1) + '</td>' +\r\n");
      out.write("            '<td>' +\r\n");
      out.write("            '  <input type=\"hidden\" name=\"criterionId[]\" value=\"' + item.criterionId + '\">' +\r\n");
      out.write("            '  <input type=\"hidden\" name=\"displayOrder[]\" value=\"' + (index + 1) + '\">' +\r\n");
      out.write("            '  <div class=\"d-flex align-items-center gap-2\">' +\r\n");
      out.write("            '    <span class=\"badge bg-light text-dark border font-monospace\">' + (item.code || 'CRIT') + '</span>' +\r\n");
      out.write("            '    <span class=\"fw-bold text-dark\">' + escapeHtml(item.name) + '</span>' +\r\n");
      out.write("            '  </div>' +\r\n");
      out.write("            '  <div class=\"text-muted small mt-1 text-truncate\" style=\"max-width: 320px;\">' + escapeHtml(item.desc || '') + '</div>' +\r\n");
      out.write("            '</td>' +\r\n");
      out.write("            '<td>' +\r\n");
      out.write("            '  <div class=\"small text-muted\">' + (item.guide ? ('<i class=\"bi bi-lightbulb text-primary me-1\"></i>' + escapeHtml(item.guide)) : '<span class=\"text-muted fst-italic\">Không có hướng dẫn</span>') + '</div>' +\r\n");
      out.write("            '</td>' +\r\n");
      out.write("            '<td class=\"text-center\">' +\r\n");
      out.write("            '  <div class=\"input-group input-group-sm mx-auto\" style=\"max-width: 120px;\">' +\r\n");
      out.write("            '    <input type=\"number\" name=\"weight[]\" class=\"form-control text-center fw-bold weight-input\" ' +\r\n");
      out.write("            '           value=\"' + item.weight + '\" min=\"0.5\" max=\"100\" step=\"0.5\" required ' +\r\n");
      out.write("            '           oninput=\"onWeightChange(' + index + ', this.value)\">' +\r\n");
      out.write("            '    <span class=\"input-group-text\">%</span>' +\r\n");
      out.write("            '  </div>' +\r\n");
      out.write("            '</td>' +\r\n");
      out.write("            '<td class=\"text-center\">' +\r\n");
      out.write("            '  <div class=\"btn-group btn-group-sm\">' +\r\n");
      out.write("            '    <button type=\"button\" class=\"btn btn-outline-secondary btn-xs\" title=\"Di chuyển lên\" ' + (index === 0 ? 'disabled' : '') + ' onclick=\"moveItem(' + index + ', -1)\">' +\r\n");
      out.write("            '      <i class=\"bi bi-chevron-up\"></i>' +\r\n");
      out.write("            '    </button>' +\r\n");
      out.write("            '    <button type=\"button\" class=\"btn btn-outline-secondary btn-xs\" title=\"Di chuyển xuống\" ' + (index === criteriaList.length - 1 ? 'disabled' : '') + ' onclick=\"moveItem(' + index + ', 1)\">' +\r\n");
      out.write("            '      <i class=\"bi bi-chevron-down\"></i>' +\r\n");
      out.write("            '    </button>' +\r\n");
      out.write("            '  </div>' +\r\n");
      out.write("            '</td>' +\r\n");
      out.write("            '<td class=\"text-center\">' +\r\n");
      out.write("            '  <button type=\"button\" class=\"btn btn-outline-danger btn-sm\" title=\"Xóa khỏi khung\" onclick=\"removeCriterion(' + index + ')\">' +\r\n");
      out.write("            '    <i class=\"bi bi-trash\"></i>' +\r\n");
      out.write("            '  </button>' +\r\n");
      out.write("            '</td>';\r\n");
      out.write("        tbody.appendChild(tr);\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    calculateTotalWeight();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function onWeightChange(index, val) {\r\n");
      out.write("    var num = parseFloat(val);\r\n");
      out.write("    criteriaList[index].weight = isNaN(num) ? 0 : num;\r\n");
      out.write("    calculateTotalWeight();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function moveItem(index, direction) {\r\n");
      out.write("    var targetIndex = index + direction;\r\n");
      out.write("    if (targetIndex < 0 || targetIndex >= criteriaList.length) return;\r\n");
      out.write("    var temp = criteriaList[index];\r\n");
      out.write("    criteriaList[index] = criteriaList[targetIndex];\r\n");
      out.write("    criteriaList[targetIndex] = temp;\r\n");
      out.write("    renderCriteriaTable();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function removeCriterion(index) {\r\n");
      out.write("    criteriaList.splice(index, 1);\r\n");
      out.write("    renderCriteriaTable();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function calculateTotalWeight() {\r\n");
      out.write("    var total = 0;\r\n");
      out.write("    var hasInvalidWeight = false;\r\n");
      out.write("\r\n");
      out.write("    criteriaList.forEach(function(item) {\r\n");
      out.write("        var w = parseFloat(item.weight) || 0;\r\n");
      out.write("        if (w <= 0) hasInvalidWeight = true;\r\n");
      out.write("        total += w;\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    // Làm tròn 2 chữ số thập phân\r\n");
      out.write("    total = Math.round(total * 100) / 100;\r\n");
      out.write("\r\n");
      out.write("    var badge = document.getElementById(\"totalWeightBadge\");\r\n");
      out.write("    var progressBar = document.getElementById(\"weightProgressBar\");\r\n");
      out.write("    var msg = document.getElementById(\"weightStatusMessage\");\r\n");
      out.write("    var btnSubmit = document.getElementById(\"btnSubmit\");\r\n");
      out.write("\r\n");
      out.write("    badge.innerText = total + \"%\";\r\n");
      out.write("    var progressWidth = Math.min(total, 100);\r\n");
      out.write("    progressBar.style.width = progressWidth + \"%\";\r\n");
      out.write("\r\n");
      out.write("    if (criteriaList.length === 0) {\r\n");
      out.write("        badge.className = \"badge fs-6 ms-2 bg-secondary\";\r\n");
      out.write("        progressBar.className = \"weight-progress-bar h-100 bg-secondary\";\r\n");
      out.write("        msg.innerHTML = '<span class=\"text-muted\"><i class=\"bi bi-info-circle me-1\"></i>Chưa có tiêu chí nào được chọn.</span>';\r\n");
      out.write("    } else if (hasInvalidWeight) {\r\n");
      out.write("        badge.className = \"badge fs-6 ms-2 bg-danger\";\r\n");
      out.write("        progressBar.className = \"weight-progress-bar h-100 bg-danger\";\r\n");
      out.write("        msg.innerHTML = '<span class=\"text-danger\"><i class=\"bi bi-exclamation-octagon-fill me-1\"></i>Có tiêu chí có trọng số &le; 0%. Vui lòng nhập trọng số &gt; 0!</span>';\r\n");
      out.write("    } else if (total === 100) {\r\n");
      out.write("        badge.className = \"badge fs-6 ms-2 bg-success\";\r\n");
      out.write("        progressBar.className = \"weight-progress-bar h-100 bg-success\";\r\n");
      out.write("        msg.innerHTML = '<span class=\"text-success\"><i class=\"bi bi-check-circle-fill me-1\"></i>Hợp lệ: Tổng trọng số đạt đúng chuẩn 100%.</span>';\r\n");
      out.write("    } else if (total < 100) {\r\n");
      out.write("        var diff = Math.round((100 - total) * 100) / 100;\r\n");
      out.write("        badge.className = \"badge fs-6 ms-2 bg-warning text-dark\";\r\n");
      out.write("        progressBar.className = \"weight-progress-bar h-100 bg-warning\";\r\n");
      out.write("        msg.innerHTML = '<span class=\"text-warning-emphasis\"><i class=\"bi bi-exclamation-triangle-fill me-1\"></i>Chưa đủ 100%: Còn thiếu ' + diff + '%. Cần phân bổ thêm.</span>';\r\n");
      out.write("    } else {\r\n");
      out.write("        var over = Math.round((total - 100) * 100) / 100;\r\n");
      out.write("        badge.className = \"badge fs-6 ms-2 bg-danger\";\r\n");
      out.write("        progressBar.className = \"weight-progress-bar h-100 bg-danger\";\r\n");
      out.write("        msg.innerHTML = '<span class=\"text-danger\"><i class=\"bi bi-x-circle-fill me-1\"></i>Vượt quá 100%: Đang dư ' + over + '%. Cần giảm bớt trọng số.</span>';\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    return { total: total, hasInvalidWeight: hasInvalidWeight };\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function validateAndSubmit(e) {\r\n");
      out.write("    var code = document.getElementById(\"frameworkCode\").value.trim();\r\n");
      out.write("    var name = document.getElementById(\"frameworkName\").value.trim();\r\n");
      out.write("    var status = document.getElementById(\"frameworkStatus\").value;\r\n");
      out.write("\r\n");
      out.write("    if (!code) {\r\n");
      out.write("        alert(\"Vui lòng nhập Mã khung năng lực!\");\r\n");
      out.write("        document.getElementById(\"frameworkCode\").focus();\r\n");
      out.write("        e.preventDefault();\r\n");
      out.write("        return false;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    if (!name) {\r\n");
      out.write("        alert(\"Vui lòng nhập Tên khung năng lực!\");\r\n");
      out.write("        document.getElementById(\"frameworkName\").focus();\r\n");
      out.write("        e.preventDefault();\r\n");
      out.write("        return false;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    if (criteriaList.length === 0) {\r\n");
      out.write("        alert(\"Khung năng lực phải có ít nhất một tiêu chí đánh giá!\");\r\n");
      out.write("        e.preventDefault();\r\n");
      out.write("        return false;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    var result = calculateTotalWeight();\r\n");
      out.write("\r\n");
      out.write("    if (result.hasInvalidWeight) {\r\n");
      out.write("        alert(\"Trọng số của tất cả tiêu chí phải lớn hơn 0%!\");\r\n");
      out.write("        e.preventDefault();\r\n");
      out.write("        return false;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    // Business rule bắt buộc: Tổng trọng số PHẢI bằng đúng 100%\r\n");
      out.write("    if (result.total !== 100) {\r\n");
      out.write("        alert(\"LỖI QUY TẮC NGHIỆP VỤ:\\nTổng trọng số của khung năng lực bắt buộc phải bằng đúng 100%!\\nHiện tại là: \" + result.total + \"%. Vui lòng điều chỉnh lại trước khi lưu.\");\r\n");
      out.write("        e.preventDefault();\r\n");
      out.write("        return false;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    return true;\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("// Modal Catalog\r\n");
      out.write("function openCriterionCatalogModal() {\r\n");
      out.write("    var modal = new bootstrap.Modal(document.getElementById(\"catalogModal\"));\r\n");
      out.write("    // Đánh dấu checked cho các tiêu chí đã có\r\n");
      out.write("    var cbs = document.querySelectorAll(\".catalog-cb\");\r\n");
      out.write("    cbs.forEach(function(cb) {\r\n");
      out.write("        var cid = cb.getAttribute(\"data-id\");\r\n");
      out.write("        var exists = criteriaList.some(function(item) { return item.criterionId === cid; });\r\n");
      out.write("        cb.checked = exists;\r\n");
      out.write("        cb.disabled = exists;\r\n");
      out.write("    });\r\n");
      out.write("    modal.show();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function filterCatalogList() {\r\n");
      out.write("    var term = document.getElementById(\"catalogSearchInput\").value.toLowerCase().trim();\r\n");
      out.write("    var rows = document.querySelectorAll(\".catalog-item-row\");\r\n");
      out.write("    rows.forEach(function(row) {\r\n");
      out.write("        var str = row.getAttribute(\"data-search\").toLowerCase();\r\n");
      out.write("        row.style.display = str.indexOf(term) !== -1 ? \"\" : \"none\";\r\n");
      out.write("    });\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function addSelectedFromCatalog() {\r\n");
      out.write("    var cbs = document.querySelectorAll(\".catalog-cb:checked:not(:disabled)\");\r\n");
      out.write("    var count = cbs.length;\r\n");
      out.write("    if (count === 0) {\r\n");
      out.write("        bootstrap.Modal.getInstance(document.getElementById(\"catalogModal\")).hide();\r\n");
      out.write("        return;\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    cbs.forEach(function(cb) {\r\n");
      out.write("        var cid = cb.getAttribute(\"data-id\");\r\n");
      out.write("        var code = cb.getAttribute(\"data-code\");\r\n");
      out.write("        var name = cb.getAttribute(\"data-name\");\r\n");
      out.write("        var desc = cb.getAttribute(\"data-desc\");\r\n");
      out.write("        var guide = cb.getAttribute(\"data-guide\");\r\n");
      out.write("\r\n");
      out.write("        criteriaList.push({\r\n");
      out.write("            id: \"\",\r\n");
      out.write("            criterionId: cid,\r\n");
      out.write("            code: code,\r\n");
      out.write("            name: name,\r\n");
      out.write("            desc: desc,\r\n");
      out.write("            guide: guide,\r\n");
      out.write("            weight: 10, // Default gợi ý 10%\r\n");
      out.write("            displayOrder: criteriaList.length + 1\r\n");
      out.write("        });\r\n");
      out.write("    });\r\n");
      out.write("\r\n");
      out.write("    // Tự động phân bổ lại trọng số đều nhau nếu tổng trọng số chưa hợp lý\r\n");
      out.write("    autoDistributeWeightsIfHelpful();\r\n");
      out.write("\r\n");
      out.write("    bootstrap.Modal.getInstance(document.getElementById(\"catalogModal\")).hide();\r\n");
      out.write("    renderCriteriaTable();\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function autoDistributeWeightsIfHelpful() {\r\n");
      out.write("    if (criteriaList.length > 0) {\r\n");
      out.write("        var total = criteriaList.reduce(function(acc, cur) { return acc + (parseFloat(cur.weight) || 0); }, 0);\r\n");
      out.write("        // Nếu tổng = 0 hoặc chưa chạm 100%, có thể chia đều 100%\r\n");
      out.write("        if (total === 0 || total > 150) {\r\n");
      out.write("            var n = criteriaList.length;\r\n");
      out.write("            var base = Math.floor((100 / n) * 10) / 10;\r\n");
      out.write("            var sum = 0;\r\n");
      out.write("            for (var i = 0; i < n - 1; i++) {\r\n");
      out.write("                criteriaList[i].weight = base;\r\n");
      out.write("                sum += base;\r\n");
      out.write("            }\r\n");
      out.write("            criteriaList[n - 1].weight = Math.round((100 - sum) * 10) / 10;\r\n");
      out.write("        }\r\n");
      out.write("    }\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("// Modal Quick Create Criterion\r\n");
      out.write("function openQuickCreateCriterionModal() {\r\n");
      out.write("    document.getElementById(\"quickCritAlert\").innerHTML = \"\";\r\n");
      out.write("    document.getElementById(\"quickCritCode\").value = \"\";\r\n");
      out.write("    document.getElementById(\"quickCritName\").value = \"\";\r\n");
      out.write("    document.getElementById(\"quickCritDesc\").value = \"\";\r\n");
      out.write("    document.getElementById(\"quickCritGuide\").value = \"\";\r\n");
